<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class filter extends lib { var $guid; var $log_id = 'collection-project'; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-filter-' . $this->guid, array($this, 'parse'), 10, 8 ); } public function allow_empty() { return in_array($this->guid, array('default_value', 'ignore_by_keyword')); } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) {} public function parse($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (is_array($item)) { if (empty($item)) { $item[0] = $this->filter('', $args, $source_link, $html, $type, $item_args, $download_args, $mode); } else { foreach ($item as &$i) { if ( $this->is_not_empty($i) || $this->allow_empty() ) { if ( !preg_match('/\(disallowed:[^\)]*\)/i', $i) ) $i = $this->filter($i, $args, $source_link, $html, $type, $item_args, $download_args, $mode); } } } } else { if ( $this->is_not_empty($item) || $this->allow_empty() ) { if ( !preg_match('/\(disallowed:[^\)]*\)/i', $item) ) $item = $this->filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode); } } return $item; } } ?>